def transform(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    # find wall color: most common non-background? wall = color forming long straight segments; find colors
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    colors=[c for c in cnt if c!=bg]
    # wall = color with most cells
    wall=max(colors,key=lambda c:cnt[c])
    # wall segments: for each row, does it have wall on left or right end?
    # regions: rows with wall contiguous
    # find dots: cells not bg and not wall
    dots=[(r,c) for r in range(H) for c in range(W) if g[r][c] not in (bg,wall)]
    # region of a row: wall side
    def wall_side(r):
        row=g[r]
        if row[0]==wall: return 'L'
        if row[-1]==wall: return 'R'
        return None
    # region starts
    sides=[(r,wall_side(r)) for r in range(H)]
    # contiguous regions with a side
    regions=[]; cur=None
    for r,s in sides:
        if s is None:
            if cur: regions.append(cur); cur=None
        else:
            if cur and cur['side']==s: cur['end']=r
            elif cur and cur['side']!=s:
                regions.append(cur); cur={'side':s,'start':r,'end':r}
            else: cur={'side':s,'start':r,'end':r}
    if cur: regions.append(cur)
    for d in dots:
        r,c=d
        col=g[r][c]
        reg=next(rg for rg in regions if rg['start']<=r<=rg['end'])
        s=reg['side']
        # fill from wall to dot in own region
        if s=='L':
            for cc in range(1,c): out[r][cc]=col
        else:
            for cc in range(c+1,W-1): out[r][cc]=col
        out[r][c]=4
        # project into opposite-side region: row = r - reg['start'] from that region's start
        opp=[rg for rg in regions if rg['side']!=s]
        if opp:
            o=opp[0]
            rr=o['start']+(r-reg['start'])
            if rr<=o['end']:
                if o['side']=='L':
                    for cc in range(1,W): out[rr][cc]=col
                else:
                    for cc in range(0,W-1): out[rr][cc]=col
    return out
